    def _handle_field_for_search(self, field, fixed_fields, named_fields,
            type_conversions, group_to_name_map, name_to_group_map, 
            name_types, group_index):
        """Handle a field for search mode.

        For left- and center-aligned untyped fields, use .+? instead of
        .{width,}? so that we stop at whitespace rather than enforcing width.
        """
        # First: lose the braces
        field = field[1:-1]

        # Now figure whether this is an anonymous or named field, and whether
        # there's any format specification
        format = ''
        if field and field[0].isalpha():
            if ':' in field:
                name, format = field.split(':')
            else:
                name = field
            if name in name_to_group_map:
                if name_types.get(name) != format:
                    raise RepeatedNameError('field type %r for field "%s" '
                        'does not match previous seen type %r' % (format,
                        name, name_types[name]))
                group = name_to_group_map[name]
                return '(?P=%s)' % group, group_index
            else:
                # Create new group name
                g = name.replace('.', '_').replace('[', '_').replace(']', '_')
                n = 1
                while g in group_to_name_map:
                    n += 1
                    if '.' in name:
                        g = name.replace('.', '_' * n)
                    elif '_' in name:
                        g = name.replace('_', '_' * n)
                    else:
                        raise KeyError('duplicated group name %r' % (name,))
                group_to_name_map[g] = name
                name_to_group_map[name] = g
                name_types[name] = format
                group = g
            named_fields.append(group)
            wrap = '(?P<%s>%%s)' % group
        else:
            fixed_fields.append(group_index)
            wrap = '(%s)'
            if ':' in field:
                format = field[1:]
            group = group_index

        # Decode the format specification
        format = extract_format(format, self._extra_types)
        type = format['type']
        is_numeric = type and type in 'n%fegdobh'

        # Handle extra types
        if type in self._extra_types:
            type_converter = self._extra_types[type]
            s = getattr(type_converter, 'pattern', r'.+?')
            regex_group_count = getattr(type_converter, 'regex_group_count', 0)
            if regex_group_count is None:
                regex_group_count = 0
            group_index += regex_group_count
            def f(string, m):
                return type_converter(string)
            type_conversions[group] = f

        elif type == 'l':
            s = r'[A-Za-z]+'
        elif type:
            s = r'\%s+' % type
        elif format.get('precision'):
            if format.get('width'):
                s = '.{%s,%s}?' % (format['width'], format['precision'])
            else:
                s = '.{1,%s}?' % format['precision']
        elif format.get('width'):
            # KEY CHANGE: For left/center alignment, don't enforce minimum width
            # Just use .+? which will be constrained by the trailing [^ ]*
            align = format['align']
            if align in ('<', '^'):
                s = '.+?'
            else:
                s = '.{%s,}?' % format['width']
        else:
            s = '.+?'

        align = format['align']
        fill = format['fill']

        # Handle numeric-specific things like fill and sign
        if is_numeric:
            if align == '=':
                if not fill:
                    fill = '0'
                s = '%s*' % fill + s
            s = r'[-+ ]?' + s

        if not fill:
            fill = ' '

        # Place into a group now
        if wrap:
            s = wrap % s
            group_index += 1

        if format['width']:
            if not align:
                align = '>'

        if fill in '.\+?*[](){}^$':
            fill = '\\' + fill

        # align "=" has been handled
        if align == '<':
            s = '%s[^%s]*' % (s, fill)
        elif align == '>':
            s = '%s*%s' % (fill, s)
        elif align == '^':
            s = '[^%s]*%s[^%s]*' % (fill, s, fill)

        return s, group_index


